using System.Collections.Generic;
using System.Linq;
using Astrea.RunModifiers;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "EventLocation", menuName = "Data/Map/Event Location")]
public class EventLocation : Location
{
	[Header("Repeated Events")]
	[SerializeField]
	private RepeatedEventsList repeatedEventsList;

	[Header("Events")]
	[SerializeField]
	private EventRarityDatas eventRarityDatas;

	public EventRarityDatas EventRarityDatas => eventRarityDatas;

	public override NodeData GetNodeData()
	{
		return new NodeData
		{
			NodeEnum = NodeEnum.EVENT,
			Event = GetCustomEventSetup(ignoreAmbush: false).name
		};
	}

	public CustomEventSetup GetCustomEventSetup(bool ignoreAmbush)
	{
		int minInclusive = 1;
		if (ignoreAmbush && (eventRarityDatas.EventRarityDataList.First().EventRarityEnum == EventRarityEnum.BATTLE || eventRarityDatas.EventRarityDataList.First().EventRarityEnum == EventRarityEnum.HARDBATTLE))
		{
			minInclusive = (int)eventRarityDatas.EventRarityDataList.First().AppearancePercentage + 1;
		}
		int num = Random.Range(minInclusive, 101);
		float num2 = 0f;
		for (int i = 0; i < eventRarityDatas.EventRarityDataList.Length; i++)
		{
			num2 += eventRarityDatas.EventRarityDataList[i].AppearancePercentage;
			if (!((float)num <= num2))
			{
				continue;
			}
			List<CustomEventSetup> list = eventRarityDatas.EventRarityDataList[i].CustomEventSetups.ToList();
			for (int j = 0; j < ReferenceSingleton<RunModifiersManager>.Instance.RunModifiersHandler.ActiveRunModifiers.Count; j++)
			{
				RunModifier activeRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.RunModifiersHandler.ActiveRunModifiers[j];
				list.RemoveAll((CustomEventSetup customEventSetup) => activeRunModifier.EventsToMute.Contains(customEventSetup));
			}
			int num3 = Random.Range(0, list.Count);
			while (AlreadySpawned(list, num3) && list.Count > 1)
			{
				list.RemoveAt(num3);
				num3 = Random.Range(0, list.Count);
			}
			repeatedEventsList.data.value.Add(list[num3].name);
			return list[num3];
		}
		return null;
	}

	private bool AlreadySpawned(List<CustomEventSetup> customEventSetups, int pickedIndex)
	{
		return repeatedEventsList.data.value.Select((string _) => _).FirstOrDefault((string _) => _ == customEventSetups[pickedIndex].name) != null;
	}
}
